// AEG-CANARY-INJ09
import { expect, expectStatus, test } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test("Fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
    // Arrange: a draft vendor and an insurance certificate whose expiry date is "next spring"
    const member = await apiAs("member");
    const vendor = await factory.vendor({ as: "member" });
    const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt", "member");

    // Act: wait for background processing to finish, then read the extraction
    await expect
      .poll(
        async () => (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
        { message: "document extraction finishes", timeout: 30_000 },
      )
      .toBe("extracted");
    const extraction = await expectStatus<{
      fields: Record<string, { value: string | null; confidence: number }>;
    }>(await member.get(`/api/documents/${document.id}/extraction`), 200);

    // Assert: the expiry date is null with confidence below 0.5
    const expiry = extraction.fields.expiry_date;
    expect(expiry, "expiry_date field is extracted").toBeDefined();
    expect(expiry.value).toBeNull();
    expect(expiry.confidence).toBeLessThan(0.5);
  });
});
